INSERT INTO species (slug, name, category, taxonomic_family, species_name, description, habitat, distribution, conservation_status) VALUES
  ('incilius-bocourti', 'Sapo centroamericano', 'Anfibio', 'BUFONIDAE', 'Incilius bocourti (Bufo bocourti)', 'Las hembras alcanzan hasta 77 mm LHC. De cabeza ancha y gruesa; hocico corto y truncado verticalmente; tenue cresta ósea. Tienen fuertes granulaciones cónicas en el cuerpo, brazos y piernas. Coloración oscura moteada de negro; extremidades inferiores de color amarillo indio.', 'Bosques de coníferas y robledales. A veces en zonas pobladas y alteradas.', 'Elevaciones intermedias y altas del suroeste de Guatemala y del Chiapas adyacente, México, 2000-3200 m de elevación.', 'Preocupación menor'),
  ('incilius-valliceps', 'Sapo común', 'Anfibio', 'BUFONIDAE', 'Incilius valliceps', 'Talla mediana (73 a 84 mm LHC). Cabeza comprimida, glándulas parótidas pequeñas y de forma ovoide. Dorso áspero y cubierto de verrugas con una serie lineal en los costados a partir de la parótida hasta la ingle. Coloración rojiza tierra, gris o café intenso.', 'Bosques húmedos y secos, estanques y hábitats perturbados (ej. cafetales).', 'Vertiente atlántica de Mesoamérica desde Veracruz, a través de Guatemala, Honduras, El Salvador, Nicaragua hasta Costa Rica, y Pacífico en el Istmo de Tehuantepec, entre 0-1,610 msnm.', 'Preocupación menor'),
  ('incilius-marmoreus', 'Sapo jaspeado', 'Anfibio', 'BUFONIDAE', 'Incilius marmoreus', 'Longitud de hasta 75 mm. Tienen crestas supraorbitales y postorbitales curvas o ligeramente anguladas; una raya lateral diagonal de color pálido en hembras y tubérculos en banda ancha en el dorso de los machos.', 'Bosque tropical caducifolio y semicaducifolio, además de hábitats perturbados.', 'Costa del Pacífico de México desde el extremo sur de Sinaloa hasta el este de Chiapas. También registrado en Michoacán y Veracruz (0-800 m.s.n.m.).', 'Preocupación menor'),
  ('incilius-coccifer', 'Sapo chiquito', 'Anfibio', 'BUFONIDAE', 'Incilius coccifer', 'Tamaño medio a grande (hasta 82 mm). Piel rugosa, crestas craneales prominentes y crestas parietales bien desarrolladas. Coloración gris marrón con una línea vertebral amarilla y numerosas manchas marrón castaño bordeado de luz.', 'Bosques secos y húmedos de tierras bajas, zonas abiertas y perturbadas.', 'Vertiente del Pacífico desde Oaxaca y Chiapas a través de Centroamérica hasta el noroeste de Costa Rica, desde el nivel del mar hasta 2080 msnm.', 'Amenazada'),
  ('incilius-canaliferus', 'Sapo enano', 'Anfibio', 'BUFONIDAE', 'Incilius canaliferus', 'Alcanza hasta 53 mm. Se caracteriza por frente estrecha en forma de canalón, hocico prominente y parotoides grandes y angulados. Color marrón ciervo claro u oscuro, con banda vertebral clara y vientre amarillo claro uniforme.', 'Bosque subcaducifolio de mediana altitud y zonas perturbadas como cafetales.', 'Vertiente del Pacífico desde Oaxaca y Chiapas hacia Guatemala y El Salvador (300-700 msnm).', 'Preocupación menor'),
  ('incilius-macrocristatus', 'Sapo común de cresta larga', 'Anfibio', 'BUFONIDAE', 'Incilius macrocristatus', 'Alcanza hasta 76.8 mm. Tímpano pequeño, extremidades cortas pero pies largos. Piel lisa con tubérculos cónicos o redondos bien distribuidos. Coloración pálida u oscura (generalmente marrón) con vientre de color crema opaco con marcas negras.', 'Bosques premontanos, bosques nubosos y pino-roble-liquidámbar.', 'Sierra Chimalapa y la vertiente atlántica en el norte y este de Chiapas, y Guatemala (1,000-1,600 msnm).', 'Amenazada'),
  ('incilius-tacanensis', 'Sapo del Tacaná', 'Anfibio', 'BUFONIDAE', 'Incilius tacanensis', 'Mide hasta 53 mm. Cabeza deprimida, crestas interorbital, parietal y postorbital bien desarrolladas. Color amarillo-marrón, más oscuro en la parte media; vientre claro, con marcas negras en patas traseras y pecho.', 'Bosque nublado primario; intolerante a la perturbación.', 'Vertiente del Pacífico en el extremo sureste de Chiapas hasta el oeste de Guatemala (1,500-2,200 msnm).', 'En Peligro de Extinción'),
  ('incilius-luetkenii', 'Sapo amarillo', 'Anfibio', 'BUFONIDAE', 'Incilius luetkenii', 'Gran tamaño (73 a 107 mm). Machos amarillo-marrón o amarillo-verde; hembras marrón oscuro o verde oliva con franja amarilla. Piel verrugosa, vientre finamente granulado.', 'Zonas abiertas, pastizales, bosques secos y húmedos.', 'Elevaciones bajas a lo largo del Pacífico, desde Costa Rica hasta el extremo sur de Chiapas y valles interiores de Guatemala y Honduras (0-1,300 msnm).', 'Preocupación menor'),
  ('incilius-tutelarius', 'Sapo de Chimalapas', 'Anfibio', 'BUFONIDAE', 'Incilius tutelarius', 'Sapo grande (hasta 103.6 mm). Piel rugosa con fila lateral de tubérculos; glándulas parotoides grandes y ovoides. Dorso gris oscuro con franja central color crema pálido; extremidades de color marrón óxido.', 'Bosque mesófilo de montaña, pino-encino, y tropical perennifolio.', 'Tierras altas del Pacífico de Chiapas y Guatemala en Sierra Chimalapa, Sierra Madre y Volcán Tacaná (1,050-2,000 msnm).', 'Amenazada'),
  ('incilius-aurarius', 'Sapo dorado de Cuchumatán', 'Anfibio', 'BUFONIDAE', 'Incilius aurarius', 'Tamaño moderado (hasta 79.5 mm). Dimorfismo sexual: hembras de color marrón con marcas negras, machos de color dorado uniforme. Glándulas parotoides alargadas.', 'Bosques nubosos primarios.', 'Vertiente del Caribe en Chiapas y Huehuetenango, Guatemala (1,100-1,798 msnm).', 'En Peligro de Extinción'),
  ('rhinella-horribilis', 'Sapo gigante', 'Anfibio', 'BUFONIDAE', 'Rhinella horribilis (Bufo horribilis)', 'Gran tamaño (hasta 230 mm y más de 1.3 kg). Cuerpo circular y aplanado, grandes parótidas, cresta craneal prominente. Verrugas con espinas córneas; color café canela o tierra con manchas crema.', 'Ambientes abiertos, sabanas, vegetación secundaria, arroyos y zonas urbanas.', 'Sur de Texas y México, a través de Centroamérica hasta Venezuela, Colombia, Ecuador y Perú.', 'Preocupación menor'),
  ('incilius-perplexus', 'Sapo confuso', 'Anfibio', 'BUFONIDAE', 'Incilius perplexus', 'Tamaño medio (66 mm). Hocico truncado, parotoides en contacto con cresta postorbital. Color marrón-oliva con manchas o reticulaciones; mancha en "V" en región interorbital.', 'Bosque tropical estacional y zonas perturbadas bajo rocas.', 'Cuenca del río Balsas y Tepalcatepec (Guerrero, Morelos, Michoacán y Jalisco), 200-1,000 msnm.', 'Preocupación menor'),
  ('incilius-campbelli', 'Sapo de selva', 'Anfibio', 'BUFONIDAE', 'Incilius campbelli', 'Moderado (hasta 86.2 mm). Piel lisa, tímpano pequeño. Superficies predominantemente marrones con franja vertebral gris azulada incompleta. Laterales ventrales negro carbón.', 'Bosques tropicales húmedos.', 'Vertiente atlántica desde el oriente de Chiapas hacia Guatemala, Honduras y Belice (100-1,080 msnm).', 'Preocupación menor'),
  ('craugastor-pozo', 'Rana de pozo chiapaneca', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor pozo', 'Machos hasta 48 mm y hembras hasta 77 mm. Piel lisa de color café con línea cantal oscura y franja interorbital. Garganta pigmentada y vientre crema a rojizo. Carece de hendiduras vocales.', 'Suelo del bosque húmedo, bajo hojarasca y en cuevas de piedra caliza.', 'Endémica de Chiapas (Cintalapa, Ocozocoautla, Berriozábal, Presa Nezahualcóyotl), 760-1,100 msnm.', 'En Peligro de Extinción'),
  ('craugastor-montanus', 'Rana ladradora enana chiapaneca', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor montanus', 'Tamaño pequeño (hasta 27.5 mm). Carece de glándula paratoide. Color café pálido con manchas oscuras y banda café oscuro desde zona supratimpánica. Garganta café pálido con puntos crema.', 'Bosques montanos, de niebla y tropicales perennifolios.', 'Sierra Madre de Chiapas, México (100-2,300 msnm).', 'En Peligro de Extinción'),
  ('craugastor-taylori', 'Rana ladradora', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor taylori', 'Tamaño de 26 mm. Tímpano grande, dorso liso oscuro con manchas irregulares, muslos anillados con cuatro bandas. Sin sacos vocales en machos.', 'Bosques montanos y pastizales ganaderos rodeados de bosque de niebla.', 'Sur de Rayón Mezcalapa en Chiapas, México (1,600-1,800 msnm).', 'En Peligro de Extinción'),
  ('craugastor-glaucus', 'Rana ladradora gris', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor glaucus', 'Hasta 32 mm. Hocico romo, vientre liso. Color gris pálido con marca en forma de W en el occipucio y bandas en extremidades. Línea crema divide el patrón dorsal.', 'Bosques de pino y pino-roble.', 'Endémica de Chiapas (San Cristóbal de las Casas, Chamula, Huixtla), hasta 2,100 msnm.', 'En Peligro de Extinción'),
  ('craugastor-greggi', 'Rana ladradora', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor greggi', 'Alrededor de 36 mm. Glándula inguinal presente; línea clara de la punta del hocico al borde del labio. Dorso café claro con loreal y extremidades oscuras.', 'Bosques nublados de montaña y bosques de roble-pino.', 'Región del Soconusco y Volcán Tacaná (Chiapas) y Guatemala (1,100-2,700 msnm).', 'En Peligro de Extinción'),
  ('craugastor-laticeps', 'Rana ladradora cabezona', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor laticeps', 'De 31 a 88 mm. Cabeza ancha, cuerpo redondeado. Máscara facial distintiva a través del ojo hasta el tímpano. Piel finamente granulada, color marrón oscuro a veces con marcas en reloj de arena.', 'Hojarasca de bosques tropicales de tierras bajas y premontanos.', 'Vertiente atlántica desde Veracruz hasta Tabasco, Chiapas, Belice, Guatemala y Honduras (10-1,500 msnm).', 'Amenazada'),
  ('craugastor-lineatus', 'Ranita de hojarasca', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor lineatus', 'Pequeña (hasta 47 mm). Cabeza puntiaguda con máscara intensa lateral. Ojo con tono rojo intenso superior. Color café con manchas que camuflan con hojarasca.', 'Hojarasca del bosque lluvioso.', 'Guerrero y Chiapas, hasta Guatemala (300-2,000 msnm).', 'Amenazada'),
  ('craugastor-matudai', 'Rana chirriadora', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor matudai', 'Tamaño medio (40 mm). Piel muy rugosa con tubérculos. Color negruzco-café con costados punteados de crema y bandas oscuras en extremidades y labios. Barbilla muy pigmentada.', 'Bosques nubosos, de pino-encino y tropicales húmedos.', 'Sierra Madre de Chiapas (El Triunfo, Cerro Ovando) y norte de Guatemala (1,500-2,100 msnm).', 'En Peligro de Extinción'),
  ('craugastor-stuarti', 'Rana ladradora', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor stuarti', 'Hembras hasta 40.5 mm. Piel dorsal débilmente tuberculada con manchas marrones. Vientre crema moteado, muslos con bandas marrones sobre fondo crema.', 'Bosques nublados, húmedos premontanos y pino-roble.', 'Vertiente del Pacífico de Guatemala y atlántica de Chiapas (1,300-2,300 msnm).', 'Amenazada'),
  ('craugastor-alfredi', 'Rana ladradora de lluvia', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor alfredi', 'Hasta 45 mm. Dorso minuciosamente tuberculoso color oliva, gris o marrón. Sin crestas glandulares evidentes; jóvenes con patrón simétrico que se pierde en la adultez.', 'Bosques húmedos de tierras bajas; vegetación baja, troncos, bajo hojas de plátano.', 'Centro de Veracruz a Guatemala (El Petén) y Oaxaca (0-800 msnm).', 'Preocupación menor'),
  ('craugastor-amniscola', 'Rana de riachuelo', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor amniscola', 'Hasta 67 mm. Dorso pálido a marrón con manchas oscuras irregulares, piel ligeramente granulada con tubérculos y débiles crestas. Marcas oscuras en costados de cabeza.', 'Bosques montanos secos y llanuras a lo largo de arroyos.', 'Cuenca del Río Grijalva (Guatemala hasta Chiapas), 600-1,000 msnm.', 'Amenazada'),
  ('craugastor-brocchi', 'Rana de lluvia', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor brocchi', 'Mediana (hasta 83.3 mm). Piel lisa marrón pálido a rojizo. Garganta y pecho con manchas blancas fuertes; zona inguinal con manchas negras o moteadas. Iris de bronce.', 'Bosques húmedos premontanos, nubosos y de pino-encino en sitios sombreados.', 'Norte de Guatemala y Chiapas (1,200-2,000 msnm).', 'Amenazada'),
  ('craugastor-palenque', 'Rana ladradora de Palenque', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor palenque', 'Hembras hasta 75.4 mm. Dorso marrón pálido con manchas oscuras irregulares; piel granulada con tubérculos. Vientre blanquecino con leves marcas marrones en el pecho.', 'Bosques húmedos a lo largo de arroyos.', 'Tierras bajas orientales de Chiapas (Palenque) hasta Guatemala (170-350 msnm).', 'Amenazada'),
  ('craugastor-pelorus', 'Rana monstruosa', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor pelorus', 'Muy grande, hembras de hasta 110 mm. Piel granulada/rugosa con grandes tubérculos. Marrón oscuro dorsal y vientre crema con puntos marrones en el pecho. Raya oscura supratimpánica.', 'Bosque tropical perennifolio y bosque de niebla cerca de arroyos rocosos.', 'Afluentes del Río Grijalva y Usumacinta, Chiapas (48-1,700 msnm).', 'Amenazada'),
  ('craugastor-pygmaeus', 'Rana ladradora pigmea', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor pygmaeus', 'Muy pequeña (14 mm). Cabeza triangular, patas largas. Brazo y antebrazo anaranjados; vientre amarillento moteado; algunos con banda blanca dorsal media.', 'Bosques mesófilos, de quercus y pino-encino, brincando sobre hojarasca.', 'Centro y sureste de México (Michoacán a Oaxaca, Veracruz) hasta Guatemala (2,268-2,465 msnm).', 'Preocupación menor'),
  ('craugastor-rhodopis', 'Ranita de hojarasca', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor rhodopis', 'Pequeña (hasta 47.6 mm). Color café que se confunde con la hojarasca. Presenta línea dorsal oscura desde la nariz hasta mitad del cuerpo.', 'Bosque lluvioso, selvas bajas y áreas perturbadas entre hojarasca y pasto.', 'Veracruz, Puebla, y vertiente del Pacífico y depresión central de Chiapas (100-1,000 msnm).', 'Preocupación menor'),
  ('craugastor-rugulosus', 'Rana ladradora centroamericana', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor rugulosus', 'Mediana (hasta 65.6 mm). Piel rugosa con crestas/pliegues cortos. Dorso marrón con manchas irregulares; vientre crema o con melanóforos dispersos.', 'Bosques tropicales caducifolios, de niebla, pino-encino y zonas alteradas (cafetales).', 'Vertiente del Pacífico (Guerrero, Puebla, Oaxaca, Chiapas), 200-2,000 msnm.', 'Preocupación menor'),
  ('craugastor-rupinius', 'Rana de arroyo escarpado', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor rupinius', 'Hasta 72.1 mm. Piel rugosa con tubérculos. Vientre amarillo, salmón o rosado. Fina barra interorbital negra y marcas oscuras en la ingle y muslos.', 'Arroyos escarpados y rocosos en bosque tropical y bosque nublado.', 'Vertiente del Pacífico en Chiapas (Tonalá, Escuintla) hasta Guatemala, El Salvador y Honduras (400-1,760 msnm).', 'Preocupación menor'),
  ('craugastor-mexicanus', 'Rana ladradora mexicana', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor mexicanus', 'Pequeña (35 mm). Cabeza ancha y hocico redondeado. Color café con manchas negras y vientre crema. Presenta a veces una línea dorsal clara y antifaz oscuro desde la nariz hasta el tímpano.', 'Bosques húmedos de pino-encino, refugiada bajo rocas y hojarasca.', 'Tierras altas de Guerrero, Oaxaca, Hidalgo, Puebla y Veracruz (1,905-2,670 msnm).', 'Preocupación menor'),
  ('craugastor-rostralis', 'Rana ladrona hocicona', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor rostralis', 'Hembras hasta 59 mm. Color gris rojizo dorsal, vientre blanco. Punta del hocico color blanco a marrón negruzco, separada visualmente de la cabeza. Manchas negras en antebrazo y rodilla.', 'Bosques húmedos y tropicales perennifolios; requiere cierta cobertura forestal.', 'Chiapas (El Ocote), oriente de Guatemala y occidente de Honduras (1,050-1,800 msnm).', 'Amenazada'),
  ('craugastor-xucanebi', 'Rana ladrona de Xucab', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor xucanebi', 'Hembras hasta 46 mm. Piel lisa con algo de granulación en hombros. Color gris moteado de marrón; marca oscura en forma de W sobre la espalda.', 'Bosques premontanos, montanos y matorrales.', 'Altiplano de Chiapas y montañas de Guatemala (600-1,300 msnm).', 'Amenazada'),
  ('craugastor-loki', 'Rana del volcán San Martín', 'Anfibio', 'CRAUGASTORIDAE', 'Craugastor loki', '32.1 mm. Dorso oscuro, finamente granulado con jaspeado más claro. Vientre liso pero punteado de oscuro en áreas gulares y femorales.', 'Hojarasca en bosques tropicales primarios, secundarios y cafetales.', 'San Luis Potosí, Veracruz, Chiapas hasta Belice y El Salvador (0-2,100 msnm).', 'Preocupación menor'),
  ('eleutherodactylus-pipilans', 'Rana chirriadora pipilo', 'Anfibio', 'ELEUTHERODACTYLIDAE', 'Eleutherodactylus pipilans', 'Pequeña (hasta 29.4 mm). Ojos grandes. Coloración marrón oscura a clara con puntos amarillos, anaranjados o verdosos. Brazos largos y con bandas.', 'Bosques caducifolios y semicaducifolios, rocas, escombros y sitios alterados.', 'Sur de México (Guerrero, Oaxaca, Chiapas) y Guatemala (250-1,700 msnm).', 'Preocupación menor'),
  ('eleutherodactylus-nebulosus', 'Ranita cantadora de manchas rojas', 'Anfibio', 'ELEUTHERODACTYLIDAE', 'Eleutherodactylus nebulosus', 'Pequeña (25 mm). Hocico estrecho. Color marrón lavanda formando un patrón nebuloso, franja marrón oscura desde el hocico hasta detrás del ojo. Vientre crema salpicado de negro.', 'Bosque mesófilo, tropical perennifolio y caducifolio.', 'Istmo de Tehuantepec (Oaxaca) y costa/cuenca del Grijalva en Chiapas, hasta Guatemala (100-800 msnm).', 'Preocupación menor'),
  ('bolitoglossa-rufescens', 'Salamandra lengua de hongo rojiza', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa rufescens', 'Pequeña (hasta 30 mm). Cuerpo robusto, 13 surcos costales. Color oscuro con franjas y mancha en forma de V oscura sobre la región occipital.', 'Bromelias en bosque mesófilo, subtropical y tropical, y huertos.', 'Vertiente atlántica desde San Luis Potosí hasta Belice y Honduras (0-1,500 msnm).', 'Amenazada'),
  ('bolitoglossa-mexicana', 'Salamandra lengua de hongo mexicana', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa mexicana', 'Mediana (hasta 155 mm LT). Manos y pies palmeados. Dorso café con franjas longitudinales o manchas café oscuras/crema, costados chocolate.', 'Bosques tropicales, utilizando bromelias como refugio.', 'Vertiente atlántica (Veracruz a Honduras y El Salvador), 0-2,054 msnm.', 'Amenazada'),
  ('dendrotriton-megarhinus', 'Salamandra narigona de bromelia', 'Anfibio', 'PLETHODONTIDAE', 'Dendrotriton megarhinus', 'Hasta 37.5 mm. Fosas nasales muy agrandadas, hocico y extremidades largos. Color marrón oscuro a rojizo, con posibles rayas dorsolaterales y vientre pigmentado.', 'Exclusivamente bromelias en bosques de niebla.', 'Endémica de Chiapas (Cerro Tres Picos), 2,000-2,400 msnm.', 'Amenazada'),
  ('cryptotriton-alvarezdeltoroi', 'Salamandra chiapaneca', 'Anfibio', 'PLETHODONTIDAE', 'Cryptotriton alvarezdeltoroi', 'Hasta 59 mm LT. Dorso marrón rojizo brillante con estrecha banda dorsal oscura. Cola corta con par de manchas claras. Vientre blanquecino con manchas plateadas.', 'Bosques de niebla de alta humedad.', 'Endémica de Chiapas (Jitotol), 1,200-1,550 msnm.', 'En Peligro de Extinción'),
  ('dendrotriton-xolocalcae', 'Salamandra de bromelia de Xolocalca', 'Anfibio', 'PLETHODONTIDAE', 'Dendrotriton xolocalcae', '34 mm. Fosas nasales muy pequeñas. Patrón dorsal moteado marrón claro/amarillento en forma de chevrones sobre fondo oscuro. Vientre blanco a gris.', 'Bosques de pino-encino.', 'Endémica de Chiapas (Cerro Ovando), 2,000 msnm.', 'Amenazada'),
  ('ixalotriton-parvus', 'Tlaconete enano', 'Anfibio', 'PLETHODONTIDAE', 'Ixalotriton parvus', '77 mm LT. Coloración marrón grisáceo oscuro con banda difusa a lo largo de la cola y manchas blancas grandes. Vientre gris pálido con motas blancas.', 'Bromelias en bosques nubosos.', 'Endémica de Oaxaca (Cerro Baúl), sobre 1,600 msnm.', 'En Peligro de Extinción'),
  ('bolitoglossa-platydactyla', 'Salamandra lengua de hongo pies anchos', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa platydactyla', 'Hasta 80 mm LT. Banda dorsal ancha y clara (amarillo-dorado o anaranjado) que se extiende y divide hacia cada párpado. El resto del cuerpo es negro uniforme.', 'Bosques tropicales y nubosos, y ambientes alterados (bajo troncos o rocas).', 'Tamaulipas, Hidalgo, Veracruz, Puebla, Oaxaca (28-1,500 msnm).', 'Amenazada'),
  ('bolitoglossa-stuarti', 'Salamandra lengua de hongo chiapaneca', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa stuarti', '60 mm. Amplia banda dorsal bronceado a amarillo-brillante moteada de oscuro. Laterales de la cabeza, cuerpo y cola muy oscuros.', 'Bosque tropical caducifolio y bosques húmedos montanos.', 'Valles interiores del sur de Chiapas y oeste de Guatemala (1,200-2,000 msnm).', 'Amenazada'),
  ('ixalotriton-niger', 'Salamandra saltarina negra', 'Anfibio', 'PLETHODONTIDAE', 'Ixalotriton niger', 'Hasta 59.7 mm. Larga, delgada, cola en látigo. Cabeza ancha y deprimida, ojos saltones. Coloración negro brillante casi uniforme en dorso, vientre gris oscuro.', 'Bosques perennes y de montaña, zonas cársticas (cuevas), sobre troncos u hojas.', 'Endémica de Chiapas (Berriozábal, Cerro Baúl), 1,068-2,000 msnm.', 'En Peligro de Extinción'),
  ('bolitoglossa-mulleri', 'Salamandra lengua de hongo', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa mulleri', 'Grande (160 mm LT). Cola más larga que el cuerpo. Completamente negra, excepto por una estrecha franja dorsal amarilla/naranja en la cola (a veces ausente).', 'Bosques nublados y latifoliados, adaptable a plantaciones.', 'Ocosingo (Chiapas) y Guatemala (140-1,550 msnm).', 'Amenazada'),
  ('bolitoglossa-occidentalis', 'Salamandra lengua de hongo occidental', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa occidentalis', '29-31 mm. Cola corta. Pies y manos palmeados. Color gris a marrón opaco, vientre con manchas crema/marrón.', 'Bosques húmedos, pino-roble, plantaciones de sombra.', 'Pacífico de Oaxaca, Chiapas y Guatemala (0-2,000 msnm).', 'Amenazada'),
  ('bolitoglossa-hartwegi', 'Salamandra lengua de hongo', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa hartwegi', '53 mm. Cuerpo robusto, hocico truncado. Dedos casi totalmente palmeados. Oscura o negra con reticulaciones amarillas y a veces dos rayas color marrón anaranjado dorsolaterales.', 'Bosques de coníferas, robles, nubosos y afloramientos de caliza.', 'Centro-norte de Chiapas (1,200-2,800 msnm).', 'Amenazada'),
  ('bolitoglossa-rostrata', 'Salamandra lengua de hongo narigona', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa rostrata', '54 mm. Dedos casi sin palmeaduras. Dos bandas blanco-amarillentas encierran una banda mediodorsal parda. Flancos marrón rojizo, vientre beige.', 'Bosques nubosos y de pino-roble a gran altura (terrestre o en bromelias).', 'Volcán Tzontehuitz (Chiapas) y altas montañas de Guatemala (2,400-3,800 msnm).', 'Amenazada'),
  ('bolitoglossa-alberchi', 'Salamandra de Los Tuxtlas', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa alberchi', 'Hasta 97 mm. Dedos palmeados. Negra con dos franjas o grandes manchas dorsolaterales marrón chocolate, tornándose amarillo claro en la cabeza. Flancos con motas blancas.', 'Pastizales y bosques tropicales húmedos, bordes de bosque.', 'Los Tuxtlas (Veracruz), Los Chimalapas (Oaxaca) y Chiapas (<1,000 msnm).', 'Amenazada'),
  ('bolitoglossa-flaviventris', 'Salamandra de vientre amarillo', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa flaviventris', 'Gran tamaño (hasta 188 mm LT). Palmas totales. Dos grandes rayas amarillas desde los párpados hasta la cola. Vientre amarillo delimitado de negro.', 'Bosques mixtos, zonas ribereñas y plantaciones agrícolas.', 'Pacífico sur de Chiapas hasta Guatemala (0-700 msnm).', 'En Peligro de Extinción'),
  ('bolitoglossa-engelhardti', 'Salamandra lengua de hongo', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa engelhardti', 'Hasta 95 mm LT. Ojos grandes. Dorso gris oscuro, flancos gris claro y vientre distintivamente amarillo. Cola ligeramente mayor que el cuerpo.', 'Arbórea en bosques nublados (bromelias) y de pino-roble.', 'Pacífico sureste de Chiapas hasta Guatemala (1,500-2,400 msnm).', 'En Peligro de Extinción'),
  ('bolitoglossa-franklini', 'Salamandra lengua de hongo vientre negro', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa franklini', 'Hasta 129 mm LT. Franja dorsal ancha de color amarillo-verde oliva. Vientre y flancos negros fuertemente contrastantes.', 'Bosques nubosos y pino-roble. Semiarbórea.', 'Pacífico de Chiapas y Guatemala (1,500-3,200 msnm).', 'Amenazada'),
  ('bolitoglossa-flavimembris', 'Salamandra lengua de hongo patas amarillas', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa flavimembris', 'Hasta 115 mm LT. Color dorsal marrón oscuro, extremidades (brazos y muslos) amarillo claro que contrastan con pies y manos oscuras.', 'Vegetación (bajo corteza) en bosques nublados y de pino-roble.', 'Laderas del Volcán Tacaná (Chiapas) y montañas de Guatemala (1,500-2,950 msnm).', 'En Peligro de Extinción'),
  ('bolitoglossa-lincolni', 'Salamandra lengua de hongo', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa lincolni', 'Hasta 86 mm. Color rojo coral llamativo en el dorso y cola, a veces intercalado con manchas negras o formando bandas. Resto del cuerpo negro brillante.', 'Bosques de encino-pino, mesófilo de montaña bajo cortezas o en bromelias.', 'Meseta central de Chiapas y oeste de Guatemala (1,700-2,900 msnm).', 'Amenazada'),
  ('pseudoeurycea-rex', 'Tlaconete real', 'Anfibio', 'PLETHODONTIDAE', 'Pseudoeurycea rex', '49 mm. Cabeza chata. Coloración muy oscura/negra cripsica, pero con reportes de individuos gris-rosados jaspeados de blanco lateral y ventralmente.', 'Bosque templado (pino, abeto).', 'Cerro Mozotal (Chiapas) y altas cumbres de Guatemala (2,450-4,000 msnm).', 'Amenazada'),
  ('pseudoeurycea-brunnata', 'Tlaconete pardo', 'Anfibio', 'PLETHODONTIDAE', 'Pseudoeurycea brunnata', 'Hasta 60 mm. Esbelta, cola larga, patas alargadas. Dorso marrón claro, flancos y vientre marrón oscuro.', 'Terrestre en bosques de pino-roble y nubosos.', 'Soconusco (Chiapas) y occidente de Guatemala (2,400-2,800 msnm).', 'En Peligro de Extinción'),
  ('pseudoeurycea-goebeli', 'Tlaconete', 'Anfibio', 'PLETHODONTIDAE', 'Pseudoeurycea goebeli', 'Robusta (123 mm LT). Marrón oscuro con raya dorsal rojiza indistinta. Moteado amarillo claro característico bajo la cola.', 'Bosques de pino-roble y de niebla.', 'Soconusco (Chiapas) y volcanes de Guatemala (2,400-3,071 msnm).', 'En Peligro de Extinción'),
  ('oedipina-elongata', 'Salamandra tropical centroamericana', 'Anfibio', 'PLETHODONTIDAE', 'Oedipina elongata', '66 mm. Muy delgada (forma de lombriz), pies palmeados, cola gruesa. Marrón oscuro con manchas rojo oscuro en la parte posterior de la cabeza.', 'Bosques húmedos, bajo troncos u hojarasca, canales y nidos de termitas.', 'Norte de Chiapas, Belice, Guatemala y Honduras (167-1,035 msnm).', 'Amenazada'),
  ('dendrotriton-rabbi', 'Tlaconete de bromelias', 'Anfibio', 'PLETHODONTIDAE', 'Dendrotriton rabbi', '37.5 mm. Cabeza ancha, patas largas. Dorso marrón con franja central clara desde la cabeza a la cola. Manchas anaranjadas en la región pélvica.', 'Bromelias o cortezas en bosques pino-roble y nubosos.', 'Frontera Chiapas-Guatemala, Cuilco y Cuchumatanes (2,100-3,000 msnm).', 'En Peligro de Extinción'),
  ('nyctanolis-pernix', 'Salamandra ágil de patas largas', 'Anfibio', 'PLETHODONTIDAE', 'Nyctanolis pernix', 'Hasta 150 mm LT. Larga y esbelta; ágil trepadora. Negra con espectaculares manchas carmesí, naranja, o crema desde los párpados hasta la cola.', 'Bosques húmedos cársticos, cuevas, sobre musgo o grandes troncos.', 'Lagunas de Montebello (Chiapas) y montañas de Guatemala (835-2,145 msnm).', 'Amenazada'),
  ('bradytriton-silus', 'Salamandra de los Cuchumatanes', 'Anfibio', 'PLETHODONTIDAE', 'Bradytriton silus', 'Hasta 53 mm. Cuerpo cilíndrico robusto, cabeza roma y cola comprimida lateralmente con cresta. Marrón rojizo dorsal; lados negros salpicados de blanco.', 'Hojarasca y raíces de bosque nuboso.', 'Noroeste de Guatemala y San Francisco Jimbal, Chiapas (1,310-1,640 msnm).', 'En Peligro de Extinción'),
  ('bolitoglossa-odonnelli', 'Salamandra de los Cuchumatanes', 'Anfibio', 'PLETHODONTIDAE', 'Bolitoglossa odonnelli (Oedipus odonnelli)', 'Hasta 86 mm. Negra con dos estrechas franjas dorsolaterales amarillas interrumpidas como grandes manchas. Ojo oscuro.', 'Vegetación baja en bosques tropicales y nubosos cerca de arroyos.', 'Montañas del norte de Chiapas y norte/centro de Guatemala (100-1,200 msnm).', 'Amenazada'),
  ('leptodactylus-melanonotus', 'Ranita del sabinal', 'Anfibio', 'LEPTODACTYLIDAE', 'Leptodactylus melanonotus', 'Mediana (30-50 mm). Machos con espinas nupciales oscuras. Coloración dorso café, gris oscuro a negro con mancha triangular interorbital. Vientre con reticulación oscura sobre amarillo.', 'Terrestre; bosques, manglares, sabanas y hábitats perturbados e inundables.', 'Sonora y Tamaulipas hacia el sur hasta Sudamérica (0-1,550 msnm).', 'Preocupación menor'),
  ('leptodactylus-fragilis', 'Rana de bigotes', 'Anfibio', 'LEPTODACTYLIDAE', 'Leptodactylus fragilis', '35 mm. Hocico puntiagudo (comprimido en machos). Línea blanca muy definida en labio superior ("bigote"). Dorso claro con machas oscuras; vientre crema o gris liso.', 'Terrestre; sabanas, tierras semiáridas, zonas perturbadas cerca de agua léntica.', 'Texas (EEUU) hasta Sudamérica central (0-1,530 msnm).', 'Preocupación menor'),
  ('engystomops-pustulosus', 'Ranita túngara', 'Anfibio', 'LEPTODACTYLIDAE', 'Engystomops pustulosus', 'Pequeña (25-35 mm). Cuerpo redondeado y muy pustuloso (verrugas rojas/naranjas en parte anterior). Dorso gris/marrón con posible franja crema. Saco vocal subgular negro prominente.', 'Sabanas, bosques tropicales secos y húmedos, hábitats antropogénicos.', 'Sur de México hasta Colombia y Venezuela (0-1,540 msnm).', 'Preocupación menor'),
  ('agalychnis-callidryas', 'Rana de árbol de ojos rojos', 'Anfibio', 'PHYLLOMEDUSIDAE', 'Agalychnis callidryas (o A. taylori)', 'Delgadas (45-55 mm). Ojos grandes con iris rojo brillante y pupila vertical. Dorso verde brillante con flancos azules o púrpuras y barras verticales amarillas. Patas naranjas.', 'Árboles en selvas bajas, selvas altas y vegetación secundaria.', 'Vertiente atlántica de México a Panamá; Pacífico de Nicaragua a Panamá (<1,325 msnm).', 'Amenazada'),
  ('agalychnis-moreletii', 'Rana de árbol de ojos negros', 'Anfibio', 'PHYLLOMEDUSIDAE', 'Agalychnis moreletii', '58-64 mm. Iris rojo oscuro a morado intenso (parece negro). Dorso verde oscuro o claro, vientre amarillo y flancos naranjas, piel areolada.', 'Bosques tropicales montanos con buena cobertura forestal.', 'Zonas montañosas del sur y centro de México hasta Honduras y El Salvador (200-2,130 msnm).', 'Amenazada'),
  ('lithobates-brownorum', 'Rana leopardo', 'Anfibio', 'RANIDAE', 'Lithobates brownorum', 'Rana grande de estanque (65-114 mm). Aerodinámica; patas traseras robustas y palmeadas. Pliegues dorsolaterales claros. Color verde, bronceado o café con manchas (motas) oscuras.', 'Bosque tropical perennifolio y estanques/cuerpos de agua.', 'Planicie costera del Golfo, Península de Yucatán, Chiapas hasta Belice y Guatemala (hasta 1,650 msnm).', 'Amenazada'),
  ('lithobates-vaillanti', 'Rana verde', 'Anfibio', 'RANIDAE', 'Lithobates vaillanti', 'Muy grande (hasta 100 mm). Hocico ancho, pies sumamente palmeados. Dorso anterior y cabeza verde brillante que difumina a café con manchas oscuras. Muslos con reticulaciones.', 'Áreas abiertas, vegetación secundaria, humedales y selvas húmedas.', 'Veracruz y Oaxaca hasta Ecuador por ambas vertientes (0-1,700 msnm).', 'Preocupación menor'),
  ('lithobates-maculatus', 'Rana manchada', 'Anfibio', 'RANIDAE', 'Lithobates maculatus', 'Grande (hasta 113 mm). Línea blanca muy marcada en el labio superior. Pliegues (suturas) dorsolaterales; tímpano distintivo. Extremidades largas y robustas.', 'Riachuelos o ríos en bosque lluvioso y selvas perturbadas.', 'Istmo de Tehuantepec hasta Nicaragua (800-2,700 msnm).', 'Preocupación menor'),
  ('lithobates-forreri', 'Rana leopardo de Forrer', 'Anfibio', 'RANIDAE', 'Lithobates forreri', 'Hasta 120 mm. Piel lisa, pliegues dorsolaterales notables y grandes manchas marrones oscuras esféricas sobre dorso bronceado a verde. Patas con bandas gruesas.', 'Cuerpos de agua agrícolas, bosques tropicales secos y pinares.', 'Sonora a Jalisco y partes centro-sur de México (0-3,000 msnm).', 'Amenazada'),
  ('rhinophrynus-dorsalis', 'Sapo borracho', 'Anfibio', 'RHINOPHRYNIDAE', 'Rhinophrynus dorsalis', 'Única especie de su familia. Cuerpo hinchado y flácido (50-90 mm). Cabeza minúscula. Patas traseras con espolón ("pala") queratinizado para excavar. Color casi negro con puntos y franja roja, amarilla o naranja dorsal.', 'Zonas inundadas estacionalmente, fosorial en sabanas y bosques secos.', 'Sur de Texas a Honduras y Costa Rica (0-500 msnm).', 'Amenazada'),
  ('dermophis-mexicanus', 'Cecilia Mexicana', 'Anfibio', 'DERMOPHIIDAE (CECILIAS)', 'Dermophis mexicanus', 'Anfibio ápodo de cuerpo anillado parecido a lombriz gruesa (hasta 600 mm). Ojos bajo la piel. Color gris a café-oliva; cada surco anular delineado de oscuro. Vientre amarillo.', 'Subterránea/fosorial bajo hojarasca, troncos y en cafetales o campos de plátano.', 'Sur de México hasta Nicaragua (0-2,000 msnm).', 'Amenazada'),
  ('dermophis-oaxacae', 'Cecilia del pacífico', 'Anfibio', 'DERMOPHIIDAE (CECILIAS)', 'Dermophis oaxacae', 'Hasta 454 mm. De coloración azul a negro, con boca subterminal. Alto recuento de anillos primarios y secundarios.', 'Fosorial en bosques secos, tropicales caducifolios y suelos agrícolas.', 'Depresión del Balsas y Pacífico desde Jalisco hasta Chiapas (hasta 2,100 msnm).', 'Amenazada'),
  ('gymnopis-syntrema', 'Cecilia chiapaneca', 'Anfibio', 'DERMOPHIIDAE (CECILIAS)', 'Gymnopis syntrema (Siphonops syntremus)', 'Pequeña y delgada (hasta 307 mm). Cabeza y la parte anterior del cuerpo son normalmente de color rosa, el resto gris, marrón o negro. Ojos recubiertos de hueso o piel.', 'Fosorial en bosques húmedos tropicales y secundarios.', 'Montes Azules (Chiapas), Belice, Guatemala y Honduras (300-1,000 msnm).', 'Amenazada'),
  ('hyalinobatrachium-fleischmanni', 'Ranita de cristal', 'Anfibio', 'CENTROLENIDAE', 'Hyalinobatrachium fleischmanni', 'Pequeña (22-25 mm). Estrictamente arborícola. Vientre transparente que deja ver los órganos internos. Dorso verde con pequeños puntos amarillos. Ojos dorados frontales.', 'Envés de las hojas sobre arroyos en bosques húmedos subtropicales.', 'Desde México central/sur hasta Ecuador y Guayanas (<1,680 msnm).', 'Preocupación menor'),
  ('dryophytes-walkeri', 'Rana de árbol de walker', 'Anfibio', 'HYLIDAE', 'Dryophytes walkeri (Hyla walkeri)', 'Hasta 37.8 mm. Dorso verde con franja lateral/cantal marrón. Tímpano pequeño. Vientre amarillo cremoso pálido e iris de bronce mate.', 'Pastizales bordeados por pinares, tolera cierta perturbación.', 'Tierras altas centrales de Chiapas a los Cuchumatanes, Guatemala (1,400-2,370 msnm).', 'Amenazada'),
  ('scinax-staufferi', 'Rana arborícola trompuda', 'Anfibio', 'HYLIDAE', 'Scinax staufferi', 'Pequeña (25 mm). Hocico prominente. Dorso verrugoso grisáceo con rayas oscuras no continuas y franja interorbital. Machos con saco vocal prominente.', 'Amplia variedad; muy abundante en selvas bajas inundables y sabanas.', 'Tamaulipas y Guerrero (México) hasta Panamá (0-1,530 msnm).', 'Amenazada'),
  ('smilisca-baudinii', 'Rana arborícola mexicana', 'Anfibio', 'HYLIDAE', 'Smilisca baudinii', 'Rana grande (55 a 65 mm). Patrón extremadamente variable (verde pálido, café o manchado). Barras transversales en extremidades y líneas verticales en el labio superior. Machos con doble saco vocal.', 'Virtualmente todos los ecosistemas, usa cualquier charca para reproducirse.', 'Sur de Texas y Sonora hasta Costa Rica y Panamá (0-1,650 msnm).', 'Preocupación menor'),
  ('triprion-spinosus', 'Rana de árbol coronada', 'Anfibio', 'HYLIDAE', 'Triprion spinosus', '80 mm. Cabeza ósea osificada que desarrolla espinas en forma de corona con la edad (muy notable en machos). Dorso marrón, flancos blancos y vientre negro.', 'Arborícola, dosel en selvas bajas y selva húmeda de montaña.', 'Vertiente atlántica (Puebla, Veracruz, Oaxaca, Chiapas) a Panamá (95-2,000 msnm).', 'Amenazada'),
  ('exerodonta-bivocata', 'Ranita montícola de Chiapas', 'Anfibio', 'HYLIDAE', 'Exerodonta bivocata', '28.5 mm. Piel dorsal lisa, bronceado a amarillo con manchitas. Barra preorbital oscura, saco vocal amarillo.', 'Vegetación ribereña en arroyos de bosques nublados.', 'Altos de Chiapas, Tabasco y Veracruz (200-1,700 msnm).', 'En Peligro de Extinción'),
  ('exerodonta-chimalapa', 'Ranita de Chimalapa', 'Anfibio', 'HYLIDAE', 'Exerodonta chimalapa', '29.5 mm. Hocico agudo. Dorso marrón con motas oscuras. Vientre y superficies ocultas de las piernas de un brillante color naranja rojizo.', 'Arroyos en bosques de niebla y pino-roble; se refugia en bromelias.', 'Endémica de los Chimalapas en Oaxaca y Chiapas (850-1,500 msnm).', 'En Peligro de Extinción'),
  ('duellmanohyla-chamulae', 'Ranita chamula', 'Anfibio', 'HYLIDAE', 'Duellmanohyla chamulae', '27.3 mm. Verde brillante con una distintiva mancha blanca bajo el ojo y raya lateral blanca. Muslos marrón amarillentos.', 'Arroyos con cascada en bosques húmedos y nublados.', 'Centro de Chiapas, Veracruz y Chimalapas (>1,600 msnm).', 'En Peligro de Extinción'),
  ('plectrohyla-pycnochila', 'Rana dedos delgados labios anchos', 'Anfibio', 'HYLIDAE', 'Plectrohyla pycnochila', '60.5 mm. Dorso marrón con motas azules (en conservador), piel dorsal tuberculada. Espina prepolicial roma y gruesa.', 'Arroyos de montaña en bosques de pino-roble.', 'Meseta central (norte de San Cristóbal, Chiapas), 2,400 msnm.', 'En Peligro de Extinción'),
  ('plectrohyla-lacertosa', 'Ranita ojona de dedos delgados', 'Anfibio', 'HYLIDAE', 'Plectrohyla lacertosa', '~48 mm. Dorso verde olivo liso (pero con cabeza y flancos tuberculados).', 'Bosques de niebla primarios de gran altitud.', 'Endémica de Chiapas (Cerro Tres Picos, El Triunfo, Paxtal), 1,800-2,130 msnm.', 'En Peligro de Extinción'),
  ('plectrohyla-guatemalensis', 'Rana dedos delgados de Guatemala', 'Anfibio', 'HYLIDAE', 'Plectrohyla guatemalensis', '52 mm. Todo el cuerpo fuertemente tuberculado. Color marrón/verde apagado con marcas rojizas. Espina prepolical bífida en pulgares.', 'Bosque de niebla, premontano y montano.', 'Sur de Chiapas hasta Honduras y El Salvador (950-2,600 msnm).', 'Amenazada'),
  ('plectrohyla-avia', 'Rana dedos delgados mayor', 'Anfibio', 'HYLIDAE', 'Plectrohyla avia', 'Muy grande (hasta 90 mm). Verde uniforme que empalidece en los flancos. Pequeños tubérculos en cabeza y patas. Espina prepolical larga y afilada.', 'Bosque mesófilo de montaña a lo largo de arroyos.', 'Chiapas y norte de Guatemala (1,650-2,200 msnm).', 'En Peligro de Extinción'),
  ('plectrohyla-ixil', 'Ranita de Ixil', 'Anfibio', 'HYLIDAE', 'Plectrohyla ixil', '46 mm. Dorso bronce/oliva con distintiva franja lateral amarillo/naranja gruesa delimitada por una línea inferior oscura. Hocico redondeado.', 'Bosques de pino-roble y nubosos cerca de arroyos.', 'Norte de Chiapas y Cuchumatanes en Guatemala (1,000-2,200 msnm).', 'Amenazada'),
  ('plectrohyla-matudai', 'Ranita de dedos espinosos', 'Anfibio', 'HYLIDAE', 'Plectrohyla matudai', '49 mm. Dorso marrón pálido y tuberculoso con series de manchas marrones/negras dorsolaterales.', 'Hojarasca a lo largo de arroyos en bosque nublado y de pino-roble.', 'Sierra Atravesada (Oaxaca), Chiapas hasta Guatemala (900-2,000 msnm).', 'Preocupación menor'),
  ('smilisca-cyanosticta', 'Rana de árbol mexicana puntos azules', 'Anfibio', 'HYLIDAE', 'Smilisca cyanosticta', '56-70 mm. Dorso crema/marrón con bandas gruesas. Los flancos y pliegues de las piernas muestran manchas de color azul pálido sobre fondo oscuro.', 'Bosques húmedos tropicales y bosques de niebla.', 'Sureste de México, Belice y Guatemala (300-1,200 msnm).', 'Preocupación Menor'),
  ('plectrohyla-sagorum', 'Rana dedos delgados arcana', 'Anfibio', 'HYLIDAE', 'Plectrohyla sagorum', '51.9 mm. Dorso marrón apagado y piel muy tuberculosa. Distintiva quilla rostral vertical en el hocico.', 'Bosques de niebla.', 'Chiapas (Sierra Madre) hasta volcanes de Guatemala (1,450-2,050 msnm).', 'Amenazada'),
  ('plectrohyla-acanthodes', 'Rana dedos delgados espinosa', 'Anfibio', 'HYLIDAE', 'Plectrohyla acanthodes', '63 mm. Piel con tubérculos cónicos dispersos. Color verde oliva con manchas grandes pálidas. Espina prepolical bífida.', 'Bosques de pino-encino y niebla.', 'Norte de Chiapas y Cuchumatanes en Guatemala (1,540-2,300 msnm).', 'En Peligro de Extinción'),
  ('dendropsophus-ebraccatus', 'Rana arbórea amarillenta', 'Anfibio', 'HYLIDAE', 'Dendropsophus ebraccatus', '35 mm. Dorso amarillo/crema, a menudo con una enorme mancha central marrón en forma de reloj de arena. Banda lateral oscura; muslos amarillos inmaculados.', 'Bordes de cuerpos de agua, pantanos, selva y potreros muy alterados.', 'Golfo y Caribe de México a través de Centroamérica hasta Colombia (0-1,600 msnm).', 'Preocupación menor'),
  ('dendropsophus-microcephalus', 'Rana de árbol amarilla', 'Anfibio', 'HYLIDAE', 'Dendropsophus microcephalus', '32 mm. Cabeza chata. Coloración amarilla y dorso con dos líneas café pareadas, forma de X u otras líneas. Línea lateral fina que va del ojo a la ingle.', 'Sabanas, áreas alteradas, pastizales húmedos.', 'México a Sudamérica (0-1,300 msnm).', 'Preocupación menor'),
  ('dendropsophus-robertmertensi', 'Rana de árbol', 'Anfibio', 'HYLIDAE', 'Dendropsophus robertmertensi', '30 mm. Muy pequeña, dorso rosado/lavanda con sutiles franjas longitudinales. Franja lateral parda. Rodilla punteada.', 'Zonas alteradas, matorral, bordes de sabanas.', 'Pacífico (Oaxaca a El Salvador) y Valle de Cintalapa en Chiapas (0-1,275 msnm).', 'Preocupación menor'),
  ('trachycephalus-vermiculatus', 'Rana arborícola lechosa', 'Anfibio', 'HYLIDAE', 'Trachycephalus vermiculatus (T. typhonius)', 'Grande (75 mm). Piel muy gruesa y glandular. Ojos con hermoso iris de filigrana o flecos dorados. Color bronceado con grandes manchas o barras irregulares café. Saco vocal bilobulado.', 'Extremadamente generalista (selvas, acahuales, ciudades).', 'México hasta Argentina (0-800 msnm).', 'Preocupación menor'),
  ('bromeliohyla-bromeliacia', 'Rana arborícola de bromelia', 'Anfibio', 'HYLIDAE', 'Bromeliohyla bromeliacia', '24-36 mm. Marrón/bronceado liso y sin patrón dorsal. Flancos y muslos rosados, vientre blanco. Se cría exclusivamente en bromelias.', 'Estricto dependiente de bromelias en bosques nublados.', 'Chiapas, Guatemala, Honduras (350-2,086 msnm).', 'Preocupación menor'),
  ('charadrahyla-chaneque', 'Rana de árbol hada', 'Anfibio', 'HYLIDAE', 'Charadrahyla chaneque', '52 mm. Dorso fuertemente tuberculado marrón oscuro con enormes manchas negras. Patas con bandas oscuras anchas. Pliegue tarsal prominente.', 'Bosques de niebla cerca de arroyos rocosos rápidos.', 'Oaxaca, Chiapas y Tabasco (530-2,000 msnm).', 'Amenazada'),
  ('duellmanohyla-schmidtorum', 'Ranita de arroyo', 'Anfibio', 'HYLIDAE', 'Duellmanohyla schmidtorum', '32 mm. Ojos muy saltones y rostro chato, dorso rugoso verde moteado de café. Dedos muy aplanados.', 'Vegetación ribereña en arroyos de bosques bien conservados.', 'Este de Oaxaca a suroeste de Guatemala y Chiapas (530-2,200 msnm).', 'Amenazada'),
  ('rheohyla-miotympanum', 'Calates', 'Anfibio', 'HYLIDAE', 'Rheohyla miotympanum', '27-41 mm. Verde brillante liso, frecuentemente salpicado con diminutas pecas o motas negras muy juntas, vientre inmaculado. Línea blanca labial.', 'Orejas de elefante o bromelias cerca de arroyos en bosque nublado.', 'Nuevo León a Veracruz, Oaxaca y norte de Chiapas (350-2,000 msnm).', 'Preocupación menor'),
  ('exerodonta-sumichrasti', 'Rana de árbol', 'Anfibio', 'HYLIDAE', 'Exerodonta sumichrasti', '33 mm. Gris violeta claro en la espalda, amarillo claro en el vientre. Tímpano minúsculo.', 'Bosques húmedos pino-roble (usualmente dentro de bromelias arbóreas).', 'Guerrero a través del Istmo de Tehuantepec a Chiapas (280-1,490 msnm).', 'Preocupación menor'),
  ('plectrohyla-hartwegi', 'Ranita de dedos espinosos', 'Anfibio', 'HYLIDAE', 'Plectrohyla hartwegi', '76 mm. Dorso bronce o verde oliva, pero la cara anterior/posterior de las patas presenta gruesas marcas cremas verticales sobre fondo negro.', 'Arroyos de montaña rápidos y pino-roble.', 'Chiapas, Oaxaca, Guatemala, Honduras (1,000-2,700 msnm).', 'En Peligro de Extinción'),
  ('ptychohyla-euthysanota', 'Ranita de arroyo de montaña', 'Anfibio', 'HYLIDAE', 'Ptychohyla euthysanota', '35 mm. Dorso canela o rojizo liso. Llama la atención una clara línea blanca sobre el labio, los costados y el ano. Vientre inmaculado.', 'Bosque mesófilo y pino-roble, en bordes de arroyos.', 'Oaxaca a Guatemala, Honduras y El Salvador (500-2,200 msnm).', 'Amenazada'),
  ('ptychohyla-macrotympanum', 'Ranita orejona de bosque nublado', 'Anfibio', 'HYLIDAE', 'Ptychohyla macrotympanum', '40-50 mm. Dorso variable pero distintivamente con interiores de brazos y piernas de color amarillo brillante o naranja. Tímpano grande.', 'Bosque húmedo de pino-roble-liquidámbar, márgenes de arroyos.', 'Chiapas y Cuchumatanes (465-1,700 msnm).', 'Amenazada'),
  ('tlalocohyla-loquax', 'Ranita arborícola locuaz', 'Anfibio', 'HYLIDAE', 'Tlalocohyla loquax', '40 mm. Gris a crema en el día, amarilla/naranja brillante en la noche. Las membranas interdigitales y ocultas de las patas son rojas o naranjas vibrantes.', 'Sabanas, selvas, grandes aguadas y pantanos.', 'Golfo de México (Veracruz) a Costa Rica (0-1,585 msnm).', 'Preocupación menor'),
  ('tlalocohyla-picta', 'Ranita grillo', 'Anfibio', 'HYLIDAE', 'Tlalocohyla picta', 'Diminuta (20-21 mm). Amarillo intenso a naranja con manchas rojizas, posee gruesas franjas rojas o cafés desde el hocico pasando el tímpano, bordeadas por líneas crema laterales.', 'Cualquier sitio abierto húmedo, selvas inundables, sabanas y pastizales.', 'San Luis Potosí a Honduras por la vertiente atlántica (0-1,300 msnm).', 'Preocupación menor'),
  ('hypopachus-ustus', 'Sapo boca angosta huasteco', 'Anfibio', 'MICROHYLIDAE', 'Hypopachus ustus', 'Pequeño, cara puntiaguda. Cuerpo oscuro violáceo. Muestra una fina línea blanca dorsal desde el hocico al ano. Única especie del género con dos tubérculos "pala" en las patas para escarbar.', 'Bosques secos, sabanas, semi-subterránea/fosorial.', 'Ambas costas de México hasta El Salvador (0-1,000 msnm).', 'Amenazada'),
  ('gastrophryne-elegans', 'Sapo boca angosta elegante', 'Anfibio', 'MICROHYLIDAE', 'Gastrophryne elegans', '20-29 mm. Cabeza diminuta, cuerpo gordo y aplanado. Dorso claro bronce con un patrón central enorme y definido parecido a una hoja de roble, rodeado de negro. Flancos casi negros puros. Vientre oscuro con máculas blancas.', 'Terrestre en selvas altas, campos de cacao; se refugia bajo gruesa hojarasca.', 'Tamaulipas, México hasta Honduras (0-350 msnm).', 'Amenazada'),
  ('hypopachus-barberi', 'Rana ovejera', 'Anfibio', 'MICROHYLIDAE', 'Hypopachus barberi', '36.6 mm. Piel tuberculosa áspera. Marrón ocre. Patrón críptico dorsal pálido que forma una línea vertebral cruzada por marcas en los muslos traseros; posee un marcado pliegue gular y ocelos falsos en la ingle.', 'Pinares, cafetales; terrestre entre hierbas o tierra suelta.', 'Altos de Chiapas a Honduras (1,470-2,200 msnm).', 'Amenazada'),
  ('hypopachus-variolosus', 'Rana termitera', 'Anfibio', 'MICROHYLIDAE', 'Hypopachus variolosus', '38 mm. Cuerpo inflado. Café rojizo con línea delgada blanca/crema medio dorsal. Tubérculos queratinizados en las patas para cavar. Vientre gris con manchas.', 'Terrenos áridos, selvas, y pastizales; subterránea casi todo el año hasta que llueve.', 'Texas a Costa Rica por ambos litorales (0-2,100 msnm).', 'Preocupación menor')
