ALTER TABLE species
  ADD COLUMN IF NOT EXISTS category VARCHAR(50) NOT NULL DEFAULT 'Mamífero',
  ADD COLUMN IF NOT EXISTS taxonomic_family VARCHAR(100);

ON CONFLICT (slug) DO UPDATE SET name = EXCLUDED.name, category = EXCLUDED.category, taxonomic_family = EXCLUDED.taxonomic_family, species_name = EXCLUDED.species_name, description = EXCLUDED.description, habitat = EXCLUDED.habitat, distribution = EXCLUDED.distribution, conservation_status = EXCLUDED.conservation_status, updated_at = CURRENT_TIMESTAMP;

